class FinanceScreen extends StatefulWidget{const FinanceScreen({super.key});@override State<FinanceScreen> createState()=>_FinanceScreenState();}
class _FinanceScreenState extends State<FinanceScreen>{List<MoneyTransaction> items=[];DateTime month=DateTime(DateTime.now().year,DateTime.now().month);bool loading=true;@override void initState(){super.initState();_load();}Future<void> _load()async{items=(await StorageService.read('finance')).map(MoneyTransaction.fromJson).toList();_overdue();if(mounted)setState(()=>loading=false);}void _overdue(){final n=DateTime.now();for(final x in items){final d=DateTime.tryParse(x.dueDate);if(d!=null&&!x.isPaid&&!x.isCancelled&&d.isBefore(DateTime(n.year,n.month,n.day))){x.paymentStatus='overdue';}}}Future<void> _save()=>StorageService.write('finance',items.map((e)=>e.toJson()).toList());String _money(double v)=>'R\$ ${v.toStringAsFixed(2).replaceAll('.',',')}';String _key(DateTime d)=>DateFormat('yyyy-MM').format(d);List<MoneyTransaction> _month(DateTime d)=>items.where((x)=>x.date.startsWith(_key(d))&&!x.isCancelled).toList();double _sum(Iterable<MoneyTransaction>x,bool inc,{bool paid=false})=>x.where((m)=>m.income==inc&&(!paid||m.isPaid)).fold<double>(0.0,(s,m)=>s+m.amount);double _balance()=>items.where((x)=>x.isPaid&&!x.isCancelled).fold<double>(0.0,(s,x)=>s+(x.income?x.amount:-x.amount));double _committed(DateTime d)=>_month(d).where((x)=>!x.income&&!x.isPaid).fold<double>(0.0,(s,x)=>s+x.amount);
 Future<void> _addMenu()async{final c=await showModalBottomSheet<String>(context:context,builder:(x)=>SafeArea(child:Column(mainAxisSize:MainAxisSize.min,children:[ListTile(title:const Text('Nova entrada'),onTap:()=>Navigator.pop(x,'in')),ListTile(title:const Text('Nova despesa'),onTap:()=>Navigator.pop(x,'out')),ListTile(title:const Text('Compra parcelada'),onTap:()=>Navigator.pop(x,'inst')),ListTile(title:const Text('Despesa recorrente'),onTap:()=>Navigator.pop(x,'rec'))])));if(c=='in')await _single(true);else if(c=='out')await _single(false);else if(c=='inst')await _installment();else if(c=='rec')await _recurring();}
 Future<void> _single(bool income)async{final d=TextEditingController(),a=TextEditingController();String cat=income?'Salário':'Outros',status='paid';final cats=income?incomeCategories:expenseCategories;final ok=await showDialog<bool>(context:context,builder:(x)=>AlertDialog(title:Text(income?'Nova entrada':'Nova despesa'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:d,decoration:const InputDecoration(labelText:'Descrição')),TextField(controller:a,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Valor',prefixText:'R\$ ')),DropdownButtonFormField<String>(initialValue:cat,items:cats.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v){if(v!=null)cat=v;}),if(!income)DropdownButtonFormField<String>(initialValue:status,items:const[DropdownMenuItem(value:'paid',child:Text('Pago/realizado')),DropdownMenuItem(value:'pending',child:Text('Previsto'))],onChanged:(v){if(v!=null)status=v;})]),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Salvar'))]));final v=double.tryParse(a.text.replaceAll(',','.'));if(ok!=true||d.text.trim().isEmpty||v==null||v<=0)return;final date=DateFormat('yyyy-MM-dd').format(DateTime.now());items.add(MoneyTransaction(id:DateTime.now().microsecondsSinceEpoch.toString(),date:date,description:d.text.trim(),category:cat,amount:v,income:income,paymentStatus:income?'paid':status,dueDate:date,paidDate:status=='paid'?date:null));await _save();if(mounted)setState((){});}
 Future<void> _installment()async{final d=TextEditingController(),total=TextEditingController(),count=TextEditingController(text:'2');String cat='Outros';final ok=await showDialog<bool>(context:context,builder:(x)=>AlertDialog(title:const Text('Compra parcelada'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:d,decoration:const InputDecoration(labelText:'Descrição')),TextField(controller:total,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Valor total',prefixText:'R\$ ')),TextField(controller:count,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Quantidade de parcelas')),DropdownButtonFormField<String>(initialValue:cat,items:expenseCategories.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v){if(v!=null)cat=v;})]),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Criar'))]));final value=double.tryParse(total.text.replaceAll(',','.'));final n=int.tryParse(count.text);if(ok!=true||d.text.trim().isEmpty||value==null||value<=0||n==null||n<2)return;final group=DateTime.now().microsecondsSinceEpoch.toString();final each=value/n;double used=0;for(var i=1;i<=n;i++){final due=DateTime(DateTime.now().year,DateTime.now().month+i-1,DateTime.now().day);final amount=i==n?double.parse((value-used).toStringAsFixed(2)):double.parse(each.toStringAsFixed(2));used+=amount;final date=DateFormat('yyyy-MM-dd').format(due);final paid=due.isBefore(DateTime.now())||DateUtils.isSameDay(due,DateTime.now());items.add(MoneyTransaction(id:'$group-$i',date:date,description:d.text.trim(),category:cat,amount:amount,income:false,paymentStatus:paid?'paid':'pending',isInstallment:true,installmentGroupId:group,totalInstallments:n,installmentNumber:i,totalAmount:value,installmentAmount:amount,dueDate:date,paidDate:paid?date:null));}await _save();if(mounted)setState((){});}
 Future<void> _recurring()async{final d=TextEditingController(),a=TextEditingController(),count=TextEditingController(text:'12');String cat='Outros';final ok=await showDialog<bool>(context:context,builder:(x)=>AlertDialog(title:const Text('Despesa recorrente'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:d,decoration:const InputDecoration(labelText:'Descrição')),TextField(controller:a,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Valor mensal',prefixText:'R\$ ')),TextField(controller:count,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Meses')),DropdownButtonFormField<String>(initialValue:cat,items:expenseCategories.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v){if(v!=null)cat=v;})]),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Criar'))]));final value=double.tryParse(a.text.replaceAll(',','.'));final n=int.tryParse(count.text);if(ok!=true||d.text.trim().isEmpty||value==null||value<=0||n==null||n<1)return;final group=DateTime.now().microsecondsSinceEpoch.toString();for(var i=0;i<n;i++){final due=DateTime(DateTime.now().year,DateTime.now().month+i,DateTime.now().day);final date=DateFormat('yyyy-MM-dd').format(due);final paid=due.isBefore(DateTime.now())||DateUtils.isSameDay(due,DateTime.now());items.add(MoneyTransaction(id:'r-$group-$i',date:date,description:d.text.trim(),category:cat,amount:value,income:false,paymentStatus:paid?'paid':'pending',isRecurring:true,recurrenceGroupId:group,recurrenceFrequency:'monthly',recurrenceStartDate:date,dueDate:date,paidDate:paid?date:null));}await _save();if(mounted)setState((){});}
 Future<void> _toggle(MoneyTransaction x)async{x.paymentStatus=x.isPaid?'pending':'paid';x.paidDate=x.isPaid?null:DateFormat('yyyy-MM-dd').format(DateTime.now());await _save();if(mounted)setState((){});}Future<void> _delete(MoneyTransaction x)async{String scope='one';if(x.isInstallment||x.isRecurring){scope=await showDialog<String>(context:context,builder:(d)=>AlertDialog(title:const Text('Excluir'),actions:[TextButton(onPressed:()=>Navigator.pop(d,'one'),child:const Text('SOMENTE ESTA')),TextButton(onPressed:()=>Navigator.pop(d,'future'),child:const Text('ESTA E PRÓXIMAS')),FilledButton(onPressed:()=>Navigator.pop(d,'all'),child:const Text('TODA A SÉRIE'))]))??'cancel';}if(scope=='cancel')return;items.removeWhere((e){if(scope=='one')return e.id==x.id;if(x.isInstallment)return e.installmentGroupId==x.installmentGroupId&&(scope=='all'||e.installmentNumber>=x.installmentNumber);if(x.isRecurring)return e.recurrenceGroupId==x.recurrenceGroupId&&(scope=='all'||e.date.compareTo(x.date)>=0);return false;});await _save();if(mounted)setState((){});}
 @override Widget build(BuildContext context){if(loading)return const Center(child:CircularProgressIndicator());final cur=_month(month);final inc=_sum(cur,true,paid:true),out=_sum(cur,false,paid:true);final cats=<String,double>{};for(final x in cur.where((e)=>!e.income)){cats[x.category]=(cats[x.category]??0)+x.amount;}final months=List.generate(6,(i)=>DateTime(month.year,month.month-5+i));return SafeArea(child:ListView(padding:const EdgeInsets.all(16),children:[Row(children:[Expanded(child:Text('Financeiro',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold))),FilledButton.icon(onPressed:_addMenu,icon:const Icon(Icons.add),label:const Text('Adicionar'))]),AppCard(child:Row(children:[IconButton(onPressed:()=>setState(()=>month=DateTime(month.year,month.month-1)),icon:const Icon(Icons.chevron_left)),Expanded(child:Text(DateFormat('MMMM yyyy','pt_BR').format(month),textAlign:TextAlign.center,style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold))),IconButton(onPressed:()=>setState(()=>month=DateTime(month.year,month.month+1)),icon:const Icon(Icons.chevron_right))])),Row(children:[Expanded(child:_metric('Entradas realizadas',inc)),Expanded(child:_metric('Despesas realizadas',out))]),Row(children:[Expanded(child:_metric('Saldo atual',_balance())),Expanded(child:_metric('Resultado do mês',inc-out))]),AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Compromissos e previsão',style:Theme.of(context).textTheme.titleLarge),Text('Comprometido: ${_money(_committed(month))}'),Text('Entradas previstas: ${_money(_sum(cur,true))}'),Text('Despesas previstas: ${_money(_sum(cur,false))}'),Text('Saldo projetado: ${_money(_sum(cur,true)-_sum(cur,false))}')])) ,AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Entradas x despesas — 6 meses',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:8),SizedBox(height:190,child:CustomPaint(painter:_FinanceChart(months,items,Theme.of(context).colorScheme.primary),child:const SizedBox.expand()))]),if(cats.isNotEmpty)AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Despesas por categoria',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:8),for(final e in cats.entries)_categoryBar(e.key,e.value,cats.values.fold<double>(0.0,(a,b)=>a+b))])),const SizedBox(height:8),Text('Movimentações',style:Theme.of(context).textTheme.titleLarge),if(cur.isEmpty)const AppCard(child:Text('Nenhuma movimentação neste mês.')),...cur.map((x)=>AppCard(child:ListTile(contentPadding:EdgeInsets.zero,title:Text(x.description),subtitle:Text('${x.category} • ${x.paymentStatus}${x.isInstallment?' • ${x.installmentNumber}/${x.totalInstallments}':''}${x.isRecurring?' • recorrente':''}'),trailing:PopupMenuButton<String>(onSelected:(v){if(v=='pay')_toggle(x);if(v=='delete')_delete(x);},itemBuilder:(_)=>const[PopupMenuItem(value:'pay',child:Text('Marcar pago/previsto')),PopupMenuItem(value:'delete',child:Text('Excluir'))]))))]));}
 Widget _metric(String l,double v)=>AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(_money(v),style:const TextStyle(fontWeight:FontWeight.bold)),Text(l,style:Theme.of(context).textTheme.bodySmall)]));Widget _categoryBar(String n,double v,double total){return Padding(padding:const EdgeInsets.only(bottom:10),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(n),Text(_money(v))]),LinearProgressIndicator(value:total<=0?0:v/total)]));}}
class _FinanceChart extends CustomPainter{final List<DateTime> months;final List<MoneyTransaction> items;final Color color;_FinanceChart(this.months,this.items,this.color);@override void paint(Canvas c,Size s){final inc=<double>[];final out=<double>[];for(final m in months){final key=DateFormat('yyyy-MM').format(m);inc.add(items.where((x)=>x.date.startsWith(key)&&x.income&&x.isPaid&&!x.isCancelled).fold<double>(0.0,(a,x)=>a+x.amount));out.add(items.where((x)=>x.date.startsWith(key)&&!x.income&&x.isPaid&&!x.isCancelled).fold<double>(0.0,(a,x)=>a+x.amount));}final maxValue=[...inc,...out].fold<double>(0.0,(a,b)=>a>b?a:b);final range=maxValue<=0?1.0:maxValue;final p1=Paint()..color=color..strokeWidth=3..style=PaintingStyle.stroke;final p2=Paint()..color=Colors.grey..strokeWidth=3..style=PaintingStyle.stroke;void drawLine(List<double> vals,Paint p){final path=Path();for(var i=0;i<vals.length;i++){final x=vals.length==1?s.width/2:i*s.width/(vals.length-1);final y=s.height-20-vals[i]/range*(s.height-45);if(i==0){path.moveTo(x,y);}else{path.lineTo(x,y);}}c.drawPath(path,p);}drawLine(inc,p1);drawLine(out,p2);}@override bool shouldRepaint(covariant _FinanceChart old)=>old.months!=months||old.items!=items||old.color!=color;}
